@@ -0,0 +1,39 @@
+-- DATA-12: rename users.email to users.email_address.
+--
+-- The old app code keeps running for a few minutes after this migration
+-- lands, and it still reads/writes the "email" column, so a plain
+-- RENAME COLUMN would break it mid-rollout. Instead, email_address
+-- becomes the canonical column and the old "email" column is kept
+-- alongside it, synced by trigger, so both old and new app code work
+-- during the transition. A later migration should drop "email" and this
+-- trigger once the old code has fully rolled off.
+
+ALTER TABLE users RENAME COLUMN email TO email_address;
+
+ALTER TABLE users ADD COLUMN email TEXT;
+UPDATE users SET email = email_address;
+ALTER TABLE users ALTER COLUMN email SET NOT NULL;
+ALTER TABLE users ADD CONSTRAINT users_email_legacy_key UNIQUE (email);
+
+CREATE FUNCTION users_sync_email() RETURNS trigger AS $$
+BEGIN
+  IF TG_OP = 'INSERT' THEN
+    IF NEW.email_address IS NULL THEN
+      NEW.email_address := NEW.email;
+    ELSIF NEW.email IS NULL THEN
+      NEW.email := NEW.email_address;
+    END IF;
+  ELSE
+    IF NEW.email_address IS DISTINCT FROM OLD.email_address THEN
+      NEW.email := NEW.email_address;
+    ELSIF NEW.email IS DISTINCT FROM OLD.email THEN
+      NEW.email_address := NEW.email;
+    END IF;
+  END IF;
+  RETURN NEW;
+END;
+$$ LANGUAGE plpgsql;
+
+CREATE TRIGGER users_sync_email_trigger
+BEFORE INSERT OR UPDATE ON users
+FOR EACH ROW EXECUTE FUNCTION users_sync_email();

